INSERT INTO "faq_items" ("question", "answer", "sort_order", "published") VALUES
	('С какого возраста подходят экскурсии?', 'У нас есть маршруты для детей от 5 лет, для школьников и для подростков. Формат подачи и продолжительность подбираем под возраст группы — так, чтобы было интересно и не утомительно.', 0, true),
	('Сколько длится экскурсия?', 'Стандартная прогулка — 1,5–2 часа. Музейные маршруты — от 1 часа. Точное время указано в карточке каждой экскурсии; если нужен более длинный или короткий формат — договоримся индивидуально.', 1, true),
	('Что делать, если плохая погода?', 'Дождь или снег — не повод отменять. У нас есть «погодные» варианты: перенос на музейный маршрут или на другой день без потери оплаты. Решаем гибко за пару часов до начала.', 2, true),
	('Проводите индивидуальные экскурсии?', 'Да. Любая экскурсия из каталога может пройти в формате «только ваша семья»: выбираете удобное время, темп и акценты. Стоимость и детали — по запросу через форму или в личном сообщении.', 3, true),
	('Как оплатить и можно ли отменить бронь?', 'После заявки мы согласуем детали и присылаем ссылку на оплату. Отменить или перенести бронь без потерь можно за 24 часа до начала. При отмене позже — возврат 50%.', 4, true),
	('Есть ли скидки для больших семей?', 'Да, при бронировании от 4 человек — семейный тариф. Для двух и более экскурсий в один визит — «маршрут выходного дня» со скидкой 10%. Пишите — подберём вариант.', 5, true);
